  ('11000000-0000-4000-8000-000000000001', (select id from public.organizations where slug = 'fitarchive'), 'observation', 'Cropped/boxy mid-band drove Drop #001 demand', '5 of 9 drop sales were cropped/boxy outerwear in SGD 42–85; view-through on those items ran ~2x the drop average. [Synthetic demo data]', 0.7, 'a0000000-0000-4000-8000-000000000001', 9, 'e0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000001', '2026-09-10T09:00:00+08:00', '2026-09-10T09:00:00+08:00'),
  ('11000000-0000-4000-8000-000000000003', (select id from public.organizations where slug = 'fitarchive'), 'validated_result', 'Mid-price band (SGD 40–90) outsold premium (>SGD 100) 9:0', 'All completed Drop #001 orders sat in SGD 28–85; the three >SGD 95 pieces (FA-004/005/012) recorded zero checkouts despite normal traffic. Directional only — single drop, n=12 items. [Synthetic demo data]', 0.65, 'a0000000-0000-4000-8000-000000000001', 12, 'e0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000001', '2026-09-20T09:00:00+08:00', '2026-09-20T09:00:00+08:00'),
  ('11000000-0000-4000-8000-000000000002', (select id from public.organizations where slug = 'fitarchive'), 'hypothesis', 'Drop #002: shift the ladder toward entry, sharpen the persona story', 'More ≤SGD 45 entry items plus a tighter ''SG aircon layering'' story should lift save_rate without hurting inquiry_rate. [Synthetic demo data]', 0.55, 'a0000000-0000-4000-8000-000000000001', null, 'e0000000-0000-4000-8000-000000000002', 'a0000000-0000-4000-8000-000000000001', '2026-09-22T09:30:00+08:00', '2026-09-22T09:30:00+08:00');
